{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid, a halogenated carboxylic acid NSAID with an aryl chloride, had absolute oral bioavailability of 63.2% in healthy volunteers after oral vs IV dosing, directly supporting high F for the query's acidic NSAID-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "2,4-D, a chlorinated phenoxyacetic acid, showed rapid and complete oral bioavailability in humans, dogs, and rats, indicating that acidic chlorinated aromatic carboxylic acids can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "5-Hydroxytryptophan, an indole-containing amino acid with a carboxylic acid, had absolute oral bioavailability of 49% in volunteers, supporting that the query's indole/carboxylic acid combination can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Sertindole, a chloro-substituted indole-related drug, had oral bioavailability of 75% in humans, supporting high F for a chloro-substituted indole/carbazole-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Magnesium L-lactate ER caplet showed 12.49% absolute bioavailability in serum under fed conditions, a low-F data point, but this reflects an extended-release mineral salt formulation and serum magnesium measurement rather than a drug-like carboxylic acid, so it is a weak contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carprofen, a halogenated propionic acid NSAID. Highly transferable experimental analogues—especially tolfenamic acid (absolute F ~60%), 2,4-D (complete absorption), 5-HTP (49%), and sertindole (75%)—consistently show that acidic, chlorinated, indole/carbazole-like molecules achieve oral bioavailability well above 20%. The only sub-20% record comes from a magnesium lactate ER formulation and is not representative of the query's drug-like carboxylic acid scaffold. Therefore predict high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for carprofen itself are included in the provided evidence.",
    "First-pass metabolism of the query is not directly measured, though close analogues indicate adequate oral bioavailability.",
    "The low-F magnesium lactate record is confounded by extended-release formulation and serum vs urine measurement matrix."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

